Q: Using Jackson to parse multipart/form-data or application/json A: <p>CXF 3.6.x does not support directly mapping application/x-www-form-urlencoded to a Java Bean (Book). This is a framework limitation; no provider can do this. You can only receive it using a Map and then manually wrap it into an object.</p>
<pre class="lang-java prettyprint-override"><code>package org.example.controller;

import lombok.extern.slf4j.Slf4j;
import org.example.dto.Book;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;

@Slf4j
@Path(&quot;/book&quot;)
@Produces(MediaType.APPLICATION_JSON)
public class BookResource {

    // ================================
    // method 1: only JSON（use Book）
    // ================================
    @POST
    @Path(&quot;/{id}&quot;)
    @Consumes(MediaType.APPLICATION_JSON)
    public boolean setOwnerJson(
            @PathParam(&quot;id&quot;) String id,
            Book book
    ) {
        log.info(&quot;JSON request → id: {}, book: {}&quot;, id, book);
        return true;
    }

    // ================================
    // method 2: handle form(form-urlencoded + form-data)  
    // ================================
    @POST
    @Path(&quot;/{id}&quot;)
    @Consumes({
            MediaType.APPLICATION_FORM_URLENCODED,
            MediaType.MULTIPART_FORM_DATA
    })
    public boolean setOwnerForm(
            @PathParam(&quot;id&quot;) String id,
            MultivaluedMap&lt;String, String&gt; form
    ) {
        Book book = new Book();
        book.setName(form.getFirst(&quot;name&quot;));
        book.setPublisher(form.getFirst(&quot;publisher&quot;));

        log.info(&quot;request → id: {}, book: {}&quot;, id, book);
        return true;
    }
}
</code></pre>
